        s.add(z3.Or([z3.And(adj[v][u], in_S[u]) for u in range(n)]))
    dist = [[z3.Int(f"d_{i}_{j}") for j in range(n)] for i in range(n)]
    for i in range(n):
        for j in range(n):
            s.add(dist[i][j] >= 0, dist[i][j] <= n)
            if i == j:
                s.add(dist[i][j] == 0)
            else:
                s.add(z3.Implies(adj[i][j], dist[i][j] == 1))
    for i in range(n):
